# Clarified spec:
# Split a restaurant bill evenly among n people and return the list of amounts each person pays, rounded to cents. Each person pays the per-person share rounded to the nearest cent (half-cent rounds to even). If the sum of rounded shares differs from the total, the first k people pay one extra cent (or one cent less for negative totals), where k is the rounded difference between the exact total and the sum of rounded shares. For n <= 0, raise an exception. Example: total=50.0, n=3 -> each share 16.666..., rounded to 16.67; sum 50.01, so k=-1 and the last person pays 16.66: [16.67, 16.67, 16.66]. Example: total=10.015, n=2 -> each share 5.0075, rounded to 5.01; sum 10.02, k=-1 -> [5.01, 5.01].
import datetime as _dt
import decimal as _decimal
import fractions as _fractions
import json
import math as _math

import pytest

from solution import split_bill  # noqa: E402  (put your implementation in solution.py)

