def split_bill(total: float, n: int) -> list[float]:
    if n <= 0:
        raise ValueError("n must be a positive integer")

    # exact per-person share
    exact_share = total / n

    # round to nearest cent, half-to-even (banker's rounding)
    # Python's built-in round uses banker's rounding
    shares = [round(exact_share, 2) for _ in range(n)]

    # current sum of rounded shares
    current_sum = sum(shares)

    # difference between exact total and rounded sum, in cents
    diff_cents = round((total - current_sum) * 100)

    # distribute the difference: first k people get +1 cent (or -1 for negative totals)
    if diff_cents > 0:
        for i in range(diff_cents):
            shares[i] += 0.01
    elif diff_cents < 0:
        for i in range(-diff_cents):
            shares[i] -= 0.01

    return shares

import math

def split_bill(total: float, n: int) -> list[float]:
    if n <= 0:
        raise ValueError("n must be a positive integer")
    share = total / n
    rounded = [round(share, 2) for _ in range(n)]
    current_sum = sum(rounded)
    diff = total - current_sum
    k = round(diff * 100)
    # k > 0 means we are short; k < 0 means we are over
    if k > 0:
        for i in range(k):
            rounded[i] += 0.01
    elif k < 0:
        for i in range(-k):
            rounded[n - 1 - i] -= 0.01
    return rounded
